/**
 * Fast possession-by-possession simulation for games nobody watches. It uses the same
 * shot-probability model as the live engine, the teams' ratings, tactics, fatigue,
 * coaching, home court and injuries, so simulated and played games are comparable.
 * Every stat is generated by an event, so box scores always reconcile with the final.
 */
import { injuryTraitFactor, rollInjury } from '../core/injuries';
import { Rng, clamp } from '../core/rng';
import type { BoxLine, BoxScore, LeagueSave, Player, ScheduledGame, Team } from '../core/types';
import { makeProbability, type ShotKind } from '../game/engine/shot';
import { gameRatings, fullName } from './players';

/** Possessions per team in a game, matched to what live games produce at the chosen quarter length. */
export function basePossessions(quarterMinutes: number) {
  return 14.5 * quarterMinutes + 1.5;
}

type SimPlayer = {
  p: Player;
  r: Player['ratings'];
  line: BoxLine;
  minutes: number;
  usage: number;
  energy: number;
};

type Side = { team: Team; players: SimPlayer[]; active: SimPlayer[]; teamFouls: number };

const DEFAULT_MINUTES = [34, 34, 33, 32, 30, 22, 18, 14, 10, 8, 5, 0, 0, 0, 0];

export function newLine(p: Player, starter: boolean): BoxLine {
  return {
    playerId: p.id,
    name: fullName(p),
    starter,
    seconds: 0,
    points: 0,
    fgm: 0,
    fga: 0,
    threePm: 0,
    threePa: 0,
    ftm: 0,
    fta: 0,
    offRebounds: 0,
    defRebounds: 0,
    assists: 0,
    steals: 0,
    blocks: 0,
    turnovers: 0,
    fouls: 0,
    plusMinus: 0,
  };
}

/** Rotation order: starters, then bench priority, then anyone else healthy. */
export function rotationOrder(league: LeagueSave, team: Team): Player[] {
  const ids = [...team.starters, ...team.rotation, ...team.rosterIds].filter((id, i, a) => a.indexOf(id) === i && team.rosterIds.includes(id));
  return ids.map((id) => league.players[id]).filter((p) => p && !p.injury);
}

/** Minutes per player (sums to 240): the coach's plan if set, otherwise a standard rotation shaped by stamina and condition. */
export function planMinutes(league: LeagueSave, team: Team): Map<string, number> {
  const order = rotationOrder(league, team);
  const out = new Map<string, number>();
  let total = 0;
  order.forEach((p, i) => {
    const planned = team.minutesPlan[p.id];
    let m = planned !== undefined ? planned : DEFAULT_MINUTES[i] ?? 0;
    if (planned === undefined) m *= 0.85 + p.ratings.stamina * 0.03;
    m *= 0.7 + 0.3 * (p.condition / 100);
    m = clamp(m, 0, 42);
    out.set(p.id, m);
    total += m;
  });
  if (total <= 0) return out;
  // Normalise to 240, respecting the 42-minute ceiling.
  for (let iter = 0; iter < 4; iter++) {
    let sum = 0;
    for (const v of out.values()) sum += v;
    const f = 240 / sum;
    for (const [k, v] of out) out.set(k, clamp(v * f, 0, 44));
  }
  return out;
}

function usageOf(p: Player) {
  const r = p.ratings;
  let u = Math.pow(r.shooting * 1 + r.finishing * 0.9 + r.dribbling * 0.4 + r.athleticism * 0.2, 1.6);
  if (p.traits.includes('Selfish')) u *= 1.25;
  if (p.archetype === 'Rim Protector') u *= 0.7;
  return u;
}

function prepSide(league: LeagueSave, team: Team): Side {
  const mins = planMinutes(league, team);
  const starters = new Set(team.starters);
  const players: SimPlayer[] = team.rosterIds
    .map((id) => league.players[id])
    .filter(Boolean)
    .map((p) => ({
      p,
      r: gameRatings(p),
      line: newLine(p, starters.has(p.id) && !p.injury),
      minutes: p.injury ? 0 : mins.get(p.id) ?? 0,
      usage: usageOf(p),
      energy: 0.55 + 0.45 * (p.condition / 100),
    }));
  return { team, players, active: players.filter((s) => s.minutes > 0), teamFouls: 0 };
}

function pickBy(rng: Rng, list: SimPlayer[], w: (s: SimPlayer) => number) {
  return rng.weighted(list, (s) => (s.line.fouls >= 6 ? 0 : s.minutes) * w(s));
}

function avg(list: SimPlayer[], f: (s: SimPlayer) => number) {
  let s = 0;
  let w = 0;
  for (const x of list) {
    s += f(x) * x.minutes;
    w += x.minutes;
  }
  return w ? s / w : 5;
}

export function simulateGame(league: LeagueSave, game: ScheduledGame, rng: Rng): BoxScore {
  const home = league.teams.find((t) => t.id === game.homeId)!;
  const away = league.teams.find((t) => t.id === game.awayId)!;
  const sides: [Side, Side] = [prepSide(league, home), prepSide(league, away)];
  const q = league.settings.quarterMinutes;
  const paceF = 1 + ((home.tactics.pace + away.tactics.pace) / 2 - 3) * 0.04;
  const perTeam = Math.round(basePossessions(q) * paceF * rng.range(0.94, 1.06));
  const score: [number, number] = [0, 0];
  const quarterScores: [number, number][] = [[0, 0], [0, 0], [0, 0], [0, 0]];
  let period = 0;

  const runPeriod = (possessions: number, periodIndex: number) => {
    sides[0].teamFouls = 0;
    sides[1].teamFouls = 0;
    let off: 0 | 1 = rng.chance(0.5) ? 0 : 1;
    for (let i = 0; i < possessions * 2; i++) {
      const pts = possession(sides[off], sides[1 - off], off === 0, rng, league);
      score[off] += pts;
      quarterScores[periodIndex][off] += pts;
      off = (1 - off) as 0 | 1;
    }
  };

  for (; period < 4; period++) runPeriod(Math.round(perTeam / 4), period);
  let ot = 0;
  while (score[0] === score[1] && ot < 6) {
    quarterScores.push([0, 0]);
    runPeriod(Math.max(2, Math.round((perTeam * 5) / 48)), 4 + ot);
    ot++;
  }
  if (score[0] === score[1]) {
    // Extremely unlikely after six overtimes: a final free throw decides it.
    const s = rng.chance(0.5) ? 0 : 1;
    const shooter = pickBy(rng, sides[s].active, (x) => x.r.shooting);
    shooter.line.fta++;
    shooter.line.ftm++;
    shooter.line.points++;
    score[s]++;
    quarterScores[quarterScores.length - 1][s]++;
  }

  // Minutes and plus/minus (prorated by time on floor).
  const totalSeconds = (4 * 12 + ot * 5) * 60;
  for (const [i, side] of sides.entries()) {
    const margin = score[i] - score[1 - i];
    for (const s of side.players) {
      s.line.seconds = Math.round(((s.minutes / 240) * totalSeconds * 5) / 6) * 6;
      s.line.plusMinus = Math.round((margin * s.minutes) / 48);
    }
    // Make team minutes add exactly to 5 x game length.
    const sum = side.players.reduce((a, s) => a + s.line.seconds, 0);
    const top = side.players.slice().sort((a, b) => b.minutes - a.minutes)[0];
    if (top) top.line.seconds += totalSeconds * 5 - sum;
  }

  const injuries: BoxScore['injuries'] = [];
  for (const side of sides) {
    for (const s of side.players) {
      if (s.line.seconds <= 0) continue;
      const risk = 0.0000054 * s.line.seconds * injuryTraitFactor(s.p.traits) * (1.3 - s.energy * 0.3);
      if (rng.chance(risk)) injuries.push({ playerId: s.p.id, injury: rollInjury(rng) });
    }
  }

  return {
    gameId: game.id,
    homeId: home.id,
    awayId: away.id,
    homeScore: score[0],
    awayScore: score[1],
    quarterScores,
    overtimes: ot,
    home: sides[0].players.map((s) => s.line),
    away: sides[1].players.map((s) => s.line),
    injuries,
    played: false,
  };
}

function possession(o: Side, d: Side, home: boolean, rng: Rng, league: LeagueSave): number {
  const ot = o.team.tactics;
  const dt = d.team.tactics;
  const dDef = avg(d.active, (s) => s.r.defense + (s.p.traits.includes('Defensive Anchor') ? 0.7 : 0)) + d.team.staff.defense * 0.12;
  const oPass = avg(o.active, (s) => s.r.passing + (s.p.traits.includes('Floor General') ? 0.6 : 0));
  // Turnovers
  const toP = clamp(0.1 + (dDef - 5.5) * 0.012 + (dt.defAggression - 3) * 0.01 - (oPass - 5.5) * 0.012 + (ot.pace - 3) * 0.004, 0.06, 0.22);
  if (rng.chance(toP)) {
    const culprit = pickBy(rng, o.active, (s) => s.usage * (11 - s.r.dribbling) * 0.1 + 1);
    culprit.line.turnovers++;
    if (rng.chance(0.55)) pickBy(rng, d.active, (s) => s.r.defense + s.r.athleticism * 0.5).line.steals++;
    return 0;
  }
  // Non-shooting foul
  if (rng.chance(0.05 + (dt.defAggression - 3) * 0.01)) {
    const fouler = pickBy(rng, d.active, () => 1);
    fouler.line.fouls++;
    d.teamFouls++;
    if (d.teamFouls >= 5) {
      const fouled = pickBy(rng, o.active, (s) => s.usage);
      return freeThrows(fouled, 2, rng);
    }
  }
  let points = 0;
  for (let attempt = 0; attempt < 4; attempt++) {
    const shooter = pickBy(rng, o.active, (s) => s.usage);
    const r = shooter.r;
    const big = shooter.p.position === 'C' || shooter.p.position === 'PF';
    const wRim = r.finishing * 1.1 + r.athleticism * 0.5 + (big ? ot.postUps * 0.8 : 0);
    const wThree = Math.max(0.1, (r.shooting - 2.5) * (r.shooting - 2.5) * 0.35 * (0.6 + ot.threeRate * 0.17));
    const wMid = 3 + r.shooting * 0.3;
    const zone = rng.weighted(['rim', 'mid', 'three'] as const, (z) => (z === 'rim' ? wRim : z === 'mid' ? wMid : wThree));
    let kind: ShotKind = 'jumper';
    let distance: number;
    if (zone === 'rim') {
      distance = rng.range(1.5, 5);
      kind = (r.athleticism >= 6 || shooter.p.heightCm >= 206) && rng.chance(0.45) ? 'dunk' : big && rng.chance(0.3) ? 'hook' : 'layup';
      if (kind === 'hook') distance = rng.range(5, 9);
    } else if (zone === 'mid') distance = rng.range(9, 21.5);
    else distance = rng.range(23.6, 26.5);
    const value = zone === 'three' ? 3 : 2;
    const contestDist = clamp(rng.normal(3.2 - (dDef - 5.5) * 0.3 - (dt.defAggression - 3) * 0.12, 1.3), 0.8, 10);
    // Blocks
    if (zone !== 'three' && rng.chance(zone === 'rim' ? 0.055 + (dDef - 5.5) * 0.01 : 0.015)) {
      const blocker = pickBy(rng, d.active, (s) => s.r.defense * (s.p.heightCm / 200) * (s.p.traits.includes('Defensive Anchor') ? 1.5 : 1));
      blocker.line.blocks++;
      shooter.line.fga++;
      if (value === 3) shooter.line.threePa++;
      if (!offRebound(o, d, rng)) return points;
      continue;
    }
    const foulP = zone === 'rim' ? 0.2 : zone === 'mid' ? 0.08 : 0.03;
    const fouled = rng.chance(foulP + (dt.defAggression - 3) * 0.01);
    let p = makeProbability({
      kind,
      distance,
      ratings: r,
      heightCm: shooter.p.heightCm,
      traits: shooter.p.traits,
      contestDist,
      contestInFront: rng.chance(0.8),
      contestJumping: rng.chance(0.3),
      energy: shooter.energy * 0.92,
      form: shooter.p.form,
      quality: clamp(rng.normal(0.72 + o.team.staff.offense * 0.012, 0.16), 0, 1),
      clutch: false,
      fouled,
    });
    if (home) p += 0.012;
    const made = rng.chance(clamp(p, 0.02, 0.98));
    if (fouled) {
      const fouler = pickBy(rng, d.active, (s) => s.r.defense);
      fouler.line.fouls++;
      d.teamFouls++;
    }
    if (made) {
      shooter.line.fga++;
      shooter.line.fgm++;
      if (value === 3) {
        shooter.line.threePa++;
        shooter.line.threePm++;
      }
      shooter.line.points += value;
      points += value;
      const astP = clamp(0.56 + (oPass - 5.5) * 0.04 - (shooter.p.archetype === 'Slasher' ? 0.1 : 0), 0.3, 0.8);
      const mates = o.active.filter((s) => s !== shooter);
      if (mates.length && rng.chance(astP)) pickBy(rng, mates, (s) => s.r.passing * s.r.passing).line.assists++;
      if (fouled) points += freeThrows(shooter, 1, rng);
      return points;
    }
    if (fouled) {
      return points + freeThrows(shooter, value, rng);
    }
    shooter.line.fga++;
    if (value === 3) shooter.line.threePa++;
    if (!offRebound(o, d, rng)) return points;
  }
  return points;
}

/** Resolve a missed shot's rebound; true if the offence kept it. */
function offRebound(o: Side, d: Side, rng: Rng): boolean {
  const oReb = avg(o.active, (s) => s.r.rebounding + (s.p.traits.includes('High Motor') ? 0.7 : 0));
  const dReb = avg(d.active, (s) => s.r.rebounding);
  const p = clamp(0.24 + (oReb - dReb) * 0.025 + (o.team.tactics.rebounding - 3) * 0.02 - (d.team.tactics.rebounding - 3) * 0.015, 0.1, 0.4);
  const big = (s: SimPlayer) => (s.p.position === 'C' ? 1.6 : s.p.position === 'PF' ? 1.3 : 1);
  if (rng.chance(p)) {
    pickBy(rng, o.active, (s) => s.r.rebounding * s.r.rebounding * big(s)).line.offRebounds++;
    return true;
  }
  pickBy(rng, d.active, (s) => s.r.rebounding * s.r.rebounding * big(s)).line.defRebounds++;
  return false;
}

function freeThrows(s: SimPlayer, n: number, rng: Rng): number {
  let pts = 0;
  for (let i = 0; i < n; i++) {
    s.line.fta++;
    const p = makeProbability({
      kind: 'freeThrow',
      distance: 15,
      ratings: s.r,
      heightCm: s.p.heightCm,
      traits: s.p.traits,
      contestDist: 99,
      contestInFront: false,
      contestJumping: false,
      energy: s.energy,
      form: s.p.form,
      quality: clamp(rng.normal(0.72, 0.15), 0, 1),
      clutch: false,
      fouled: false,
    });
    if (rng.chance(p)) {
      s.line.ftm++;
      s.line.points++;
      pts++;
    }
  }
  return pts;
}
